    },
  ],
};

export const template = {
  AWSTemplateFormatVersion: "2010-09-09",
  Description: "Bucket de informes",
  Parameters: {
    Entorno: { Type: "String" },
  },
  Resources: {
    Informes: {
      Type: "AWS::S3::Bucket",
      Properties: {
        Tags: [{ Key: "entorno", Value: { Ref: "Entorno" } }],
      },
    },
  },
};

spec.code:
const decide = (action: string, resource: string) =>
  aws.iam.evaluate({
    request: {
      principal: { arn: "arn:aws:iam::123456789012:user/analista", accountId: "123456789012" },
      action,
      resource: { arn: resource, accountId: "123456789012" },
    },
    identityPolicies: [policy],
  }).decision;
assert.strictEqual(decide("s3:GetObject", "arn:aws:s3:::amzn-s3-demo-bucket-informes/2026/ventas.csv"), "Allow");

const decide = (action: string, resource: string) =>
  aws.iam.evaluate({
    request: {
      principal: { arn: "arn:aws:iam::123456789012:user/analista", accountId: "123456789012" },
      action,
      resource: { arn: resource, accountId: "123456789012" },
    },
    identityPolicies: [policy],
  }).decision;
assert.notStrictEqual(decide("s3:DeleteObject", "arn:aws:s3:::amzn-s3-demo-bucket-informes/2026/ventas.csv"), "Allow");

const decide = (action: string, resource: string) =>
  aws.iam.evaluate({
    request: {
      principal: { arn: "arn:aws:iam::123456789012:user/analista", accountId: "123456789012" },
      action,
      resource: { arn: resource, accountId: "123456789012" },
    },
    identityPolicies: [policy],
  }).decision;
assert.notStrictEqual(decide("s3:GetObject", "arn:aws:s3:::amzn-s3-demo-bucket-otro/2026/ventas.csv"), "Allow");

const sentencias = Array.isArray(policy.Statement) ? policy.Statement : [policy.Statement];
for (const sentencia of sentencias) {
  assert.ok(!("Principal" in sentencia), "Una política de identidad no debe incluir Principal");
}

